mapper.select:
SELECT *
FROM blog_favorite_article
WHERE favorite_id = #{favoriteId}
  AND article_id = #{articleId}
LIMIT 1

SELECT COUNT(1)
FROM blog_favorite_article fa
         INNER JOIN blog_favorite f ON fa.favorite_id = f.favorite_id
WHERE f.user_id = #{userId}
  AND fa.article_id = #{articleId}
  AND f.del_flag = 0

SELECT fa.*
FROM blog_favorite_article fa
         INNER JOIN blog_favorite f ON fa.favorite_id = f.favorite_id
WHERE f.user_id = #{userId}
  AND fa.article_id = #{articleId}
  AND f.del_flag = 0
